import argparse
import os
import sys
from collections import defaultdict

import networkx as nx

SCRIPT_DIR = os.path.abspath(os.path.dirname(__file__))
sys.path.insert(0, SCRIPT_DIR)

import graph_functions as gf  # noqa: E402
from phase_evidence import (  # noqa: E402
    MATERNAL_COLOR,
    PHASE_COUNT_HEADER,
    PATERNAL_COLOR,
    UNASSIGNED_COLOR,
    format_phase_counts,
    read_phase_counts,
)


def read_gfa(path):
    """Load lengths and phase blocks through Verkko's shared GFA reader."""
    graph = nx.Graph()
    gf.load_indirect_graph(path, graph)
    lengths = {node: int(data["length"]) for node, data in graph.nodes(data=True)}
    components = {
        node: component_id
        for component_id, component in enumerate(nx.connected_components(graph))
        for node in component
    }
    return lengths, components


def assignment(counts, minimum, ratio, length=0, sparsity=None):
    """Return a confident binary assignment, otherwise leave it unassigned."""
    first, second = counts
    if first + second < minimum:
        return None
    if sparsity is not None and length > (first + second) * sparsity:
        return None
    if first > ratio * second:
        return 0
    if second > ratio * first:
        return 1
    return None


def main():
    parser = argparse.ArgumentParser(
        description="Orient Hi-C/Pore-C phase blocks with parental markers and fill unassigned nodes"
    )
    parser.add_argument("--graph", required=True)
    parser.add_argument("--parental", required=True)
    parser.add_argument("--contacts", required=True)
    parser.add_argument("--marker-count", type=int, default=20)
    parser.add_argument("--marker-ratio", type=float, default=5.0)
    parser.add_argument("--marker-sparsity", type=int, default=5000)
    parser.add_argument("--weight-cap", type=int, default=1_000_000)
    parser.add_argument("--output", required=True)
    parser.add_argument("--report", required=True)
    parser.add_argument("--conflicts", required=True)
    args = parser.parse_args()

    lengths, components = read_gfa(args.graph)
    parental = read_phase_counts(args.parental)
    contacts = read_phase_counts(args.contacts)
    scores = defaultdict(lambda: [0, 0])
    shared = defaultdict(int)
    # Contact clusters have arbitrary hap1/hap2 orientation.  Choose one flip
    # per connected component by length-weighted agreement with trio markers;
    # capping the weight prevents one huge node from deciding the whole block.
    for node in parental.keys() & contacts.keys():
        parent_assignment = assignment(
            parental[node], args.marker_count, args.marker_ratio,
            lengths.get(node, 0), args.marker_sparsity
        )
        contact_assignment = assignment(contacts[node], 1, 1.0)
        if parent_assignment is None or contact_assignment is None:
            continue
        component = components.get(node, -1)
        weight = min(lengths.get(node, 1), args.weight_cap)
        shared[component] += weight
        scores[component][parent_assignment != contact_assignment] += weight

    flips = {component: values[1] > values[0] for component, values in scores.items()}
    with open(args.output, "w") as output, open(args.conflicts, "w") as conflicts:
        output.write(
            PHASE_COUNT_HEADER + "\tassignment\tsource\tconfidence\n"
        )
        conflicts.write("node\tcomponent\tparental\tcontacts_aligned\n")
        for node in lengths:
            parent_counts = parental.get(node, (0, 0))
            contact_counts = contacts.get(node, (0, 0))
            parent_assignment = assignment(
                parent_counts, args.marker_count, args.marker_ratio,
                lengths.get(node, 0), args.marker_sparsity
            )
            contact_assignment = assignment(contact_counts, 1, 1.0)
            component = components[node]
            if contact_assignment is not None and flips.get(component, False):
                contact_assignment = 1 - contact_assignment
                contact_counts = (contact_counts[1], contact_counts[0])

            source = "unassigned"
            final_counts = (0, 0)
            final_assignment = None
            # Parental evidence is authoritative.  Aligned contact evidence
            # confirms it, conflicting evidence is reported, and contacts are
            # used only to fill nodes lacking a confident parental assignment.
            if parent_assignment is not None:
                final_counts = parent_counts
                final_assignment = parent_assignment
                source = "parental"
                if contact_assignment == parent_assignment:
                    source = "parental+contacts"
                elif contact_assignment is not None:
                    source = "parental-conflict"
                    conflicts.write(
                        f"{node}\t{component}\thap{parent_assignment + 1}\thap{contact_assignment + 1}\n"
                    )
            elif contact_assignment is not None:
                final_counts = contact_counts
                final_assignment = contact_assignment
                source = "contacts-fill"

            color = UNASSIGNED_COLOR
            assignment_name = "NA"
            if final_assignment == 0:
                color = MATERNAL_COLOR
                assignment_name = "maternal"
            elif final_assignment == 1:
                color = PATERNAL_COLOR
                assignment_name = "paternal"
            total = final_counts[0] + final_counts[1]
            confidence = max(final_counts) / total if total else 0.0
            output.write(
                format_phase_counts(node, final_counts[0], final_counts[1], color)
                + f"\t{assignment_name}\t{source}\t{confidence:.6f}\n"
            )

    with open(args.report, "w") as report:
        report.write("component\tshared_weight\tagree_weight\tdisagree_weight\tflipped\tconcordance\n")
        for component in sorted(set(components.values())):
            agree, disagree = scores[component]
            total = agree + disagree
            concordance = max(agree, disagree) / total if total else 0.0
            report.write(
                f"{component}\t{shared[component]}\t{agree}\t{disagree}\t{int(flips.get(component, False))}\t{concordance:.6f}\n"
            )
            if total == 0:
                print(
                    f"WARNING: contact phase component {component} has no parental anchors; its orientation is arbitrary",
                    file=sys.stderr,
                )
            elif concordance < 0.8:
                print(
                    f"WARNING: contact phase component {component} has low parental concordance ({concordance:.3f})",
                    file=sys.stderr,
                )


if __name__ == "__main__":
    main()
